// NiFlow Update: schreibt alle aktuellen Dateien und entfernt lose Duplikate im Hauptordner.
// Ausführen im Hauptordner des Repositorys mit:  node niflow-update.mjs
import { existsSync, mkdirSync, rmSync, writeFileSync } from 'node:fs'
import { dirname } from 'node:path'

if (!existsSync('package.json')) {
  console.log('Abbruch: Bitte im Hauptordner des Repositorys ausführen (dort liegt package.json).')
  process.exit(1)
}

