for (const [path, content] of Object.entries(files)) {
  mkdirSync(dirname(path) || '.', { recursive: true })
  writeFileSync(path, content)
  console.log('Geschrieben: ' + path)
}
let removed = 0
for (const name of stray) {
  if (existsSync(name)) {
    rmSync(name, { force: true })
    removed++
    console.log('Entfernt:    ' + name)
  }
}
console.log('\nFertig: ' + Object.keys(files).length + ' Dateien geschrieben, ' + removed + ' lose Dateien entfernt.')
console.log('Weiter mit:  npm install   git add -A   git commit -m "Google Kalender"   git push')
